bool XeFG_Dx12::QuiesceWork()
{
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
    if (!_workGate.CloseAndWait(std::chrono::milliseconds(5000)))
    {
        LOG_ERROR("XeFG cleanup timed out waiting for CPU resource users; preserving owned objects");
        return false;
    }

    // A finished tag call may have recorded copies into a GAME-owned command
    // list that has not executed yet. Keep observing submissions while rejecting
    // new tags, then stop submission callbacks before taking the queue snapshot.
    {
        std::unique_lock lock(_pendingCommandMutex);
        if (!_pendingTrackingComplete ||
            !_pendingCommandsSubmitted.wait_until(lock, deadline, [this] { return _pendingCommandListCount == 0; }))
        {
            LOG_ERROR("XeFG cleanup has {} unsubmitted command lists, tracking complete {}; preserving owned objects",
                      _pendingCommandListCount, _pendingTrackingComplete);
            return false;
        }
    }

    const auto now = std::chrono::steady_clock::now();
    const auto remaining = now < deadline ? std::chrono::duration_cast<std::chrono::milliseconds>(deadline - now)
                                         : std::chrono::milliseconds(0);
    if (!_submissionGate.CloseAndWait(remaining))
    {
        LOG_ERROR("XeFG cleanup timed out waiting for command submissions; preserving owned objects");
        return false;
    }
    return true;
}

functions.void XeFG_Dx12::TrackPendingCommandList(:
void XeFG_Dx12::TrackPendingCommandList(ID3D12GraphicsCommandList* cmdList)
{
    ID3D12GraphicsCommandList* realList = nullptr;
    if (!CheckForRealObject(__FUNCTION__, cmdList, (IUnknown**) &realList))
        realList = cmdList;

    std::lock_guard lock(_pendingCommandMutex);
    for (size_t i = 0; i < _pendingCommandListCount; ++i)
        if (_pendingCommandLists[i] == realList)
            return;
    if (_pendingCommandListCount == MaxPendingCommandLists)
    {
        if (_pendingTrackingComplete)
            LOG_ERROR("XeFG pending command tracking capacity exceeded; resource cleanup will preserve objects");
        _pendingTrackingComplete = false;
        return;
    }
    // Borrowed identity only. Never dereference or Release a game command list.
    _pendingCommandLists[_pendingCommandListCount++] = realList;
}

functions.void XeFG_Dx12::BeforeCommandSubmission(:
void XeFG_Dx12::BeforeCommandSubmission(ID3D12CommandQueue* queue, UINT count,
                                       ID3D12CommandList* const* lists)
{
    bool found = false;
    {
        std::lock_guard lock(_pendingCommandMutex);
        if (_pendingCommandListCount == 0)
            return;
    }
    for (UINT i = 0; i < count && !found; ++i)
    {
        ID3D12CommandList* realList = nullptr;
        if (!CheckForRealObject(__FUNCTION__, lists[i], (IUnknown**) &realList))
            realList = lists[i];
        std::lock_guard lock(_pendingCommandMutex);
        for (size_t j = 0; j < _pendingCommandListCount; ++j)
            if (realList == _pendingCommandLists[j])
            {
                found = true;
                break;
            }
    }
    // Registration precedes the real ExecuteCommandLists and is covered by its
    // submission token. A teardown snapshot cannot miss this queue.
    if (found)
        TrackLifetimeQueue(queue);
}

functions.void XeFG_Dx12::AfterCommandSubmission(:
void XeFG_Dx12::AfterCommandSubmission(UINT count, ID3D12CommandList* const* lists)
{
    {
        std::lock_guard lock(_pendingCommandMutex);
        if (_pendingCommandListCount == 0)
            return;
    }
    for (UINT i = 0; i < count; ++i)
    {
        ID3D12CommandList* realList = nullptr;
        if (!CheckForRealObject(__FUNCTION__, lists[i], (IUnknown**) &realList))
            realList = lists[i];
        std::lock_guard lock(_pendingCommandMutex);
        for (size_t j = 0; j < _pendingCommandListCount;)
            if (realList == _pendingCommandLists[j])
                _pendingCommandLists[j] = _pendingCommandLists[--_pendingCommandListCount];
            else
                ++j;
        if (_pendingCommandListCount == 0)
            _pendingCommandsSubmitted.notify_all();
    }
}

functions.void XeFG_Dx12::DiscardPendingCommandLis:
void XeFG_Dx12::DiscardPendingCommandList(ID3D12GraphicsCommandList* cmdList)
{
    ID3D12CommandList* realList = nullptr;
    if (!CheckForRealObject(__FUNCTION__, cmdList, (IUnknown**) &realList))
        realList = cmdList;
    // A successful Reset discards a recording that was never submitted. Already
    // submitted work still requires the queue fences, irrespective of Reset.
    AfterCommandSubmission(1, &realList);
}

functions.void XeFG_Dx12::TrackLifetimeQueue(:
void XeFG_Dx12::TrackLifetimeQueue(ID3D12CommandQueue* queue)
{
    if (queue == nullptr)
        return;

    std::lock_guard lock(_lifetimeQueueMutex);
    for (size_t i = 0; i < _lifetimeQueueCount; ++i)
        if (_lifetimeQueues[i].queue == queue)
            return;

    if (_lifetimeQueueCount == MaxLifetimeQueues)
    {
        if (_queueTrackingComplete)
            LOG_ERROR("XeFG queue lifetime tracking capacity exceeded; automatic resource teardown disabled");
        _queueTrackingComplete = false;
        return;
    }
    queue->AddRef();
    _lifetimeQueues[_lifetimeQueueCount++].queue = queue;
    _objectsDrained = false;
}
